class Task:
    VALID_PRIORITIES = {"Low", "Medium", "High"}
    total_tasks = 0

    def __init__(self, title, priority="Medium"):
        self.title = title
        self.status = "Pending"
        self._priority = "Medium"
        self.priority = priority
        self.assignee = None
        Task.total_tasks += 1

    @property
    def priority(self):
        return self._priority

    @priority.setter
    def priority(self, value):
        if value in self.VALID_PRIORITIES:
            self._priority = value

    def complete(self):
        self.status = "Completed"

    def reopen(self):
        self.status = "Pending"

    def assign_to(self, developer):
        self.assignee = developer

    def get_assignee(self):
        if self.assignee is None:
            return "Unassigned"
        return self.assignee.name


class Developer:
    def __init__(self, name, role):
        self.name = name
        self.role = role

