class TaskManager:
    def __init__(self):
        self.tasks = []

    def add_task(self, task):
        self.tasks.append(task)

    def get_tasks(self):
        return self.tasks


class BugTask(Task):
    def __init__(self, title, severity, priority="Medium"):
        super().__init__(title, priority)
        self.severity = severity


class FeatureTask(Task):
    def __init__(self, title, story_points, priority="Medium"):
